sp_header_footer.client_script:
/* ==========================================================================
 * Enterprise Digital Portal — HEADER client script
 * ==========================================================================
 * Adapted from the OOTB Stock Header client script. Header/footer scripts use
 * `$scope.*` / `data.*` — NOT the `c.` controller alias.
 *
 * Responsibilities:
 *   1. sn-avatar bootstrap (avatarProfile) — without this the avatar is blank
 *   2. navbar collapse event + responsive desktop/tablet class switching
 *   3. EARLY theme resolution: applies `data-edp-theme` to <html> on every
 *      page of the portal so the EDP Sage tokens are correct before paint.
 *      Order of precedence: localStorage -> prefers-color-scheme -> light.
 * ========================================================================== */
api.controller = function ($rootScope, $scope, $timeout, $window, i18n, spAriaUtil, $element) {

    /* ---------------------------------------------------------------- 3 ----
     * Theme resolution. Runs first so the attribute is set as early as
     * possible. The Theme Toggle widget only *flips* this value.
     * -------------------------------------------------------------------- */
    var THEME_KEY = 'edp-theme';
    var THEME_ATTR = 'data-edp-theme';

    function resolveInitialTheme() {
        var stored = null;
        try {
            stored = $window.localStorage ? $window.localStorage.getItem(THEME_KEY) : null;
        } catch (storageErr) {
            stored = null; // private mode / storage disabled
        }
        if (stored === 'light' || stored === 'dark') {
            return stored;
        }
        if ($window.matchMedia && $window.matchMedia('(prefers-color-scheme: dark)').matches) {
            return 'dark';
        }
        return 'light';
    }

    var root = $window.document.documentElement;
    if (!root.getAttribute(THEME_ATTR)) {
        root.setAttribute(THEME_ATTR, resolveInitialTheme());
    }

    /* ---------------------------------------------------------------- 1 ----
     * Avatar. REQUIRED by <sn-avatar primary="avatarProfile">.
     * -------------------------------------------------------------------- */
    $scope.logoText = i18n.format(i18n.getMessage('Go to {0} Homepage'), $scope.portal.title);

    $scope.avatarProfile = {
        userID: $scope.user.sys_id,
        name: $scope.user.name,
        initials: $window.NOW ? $window.NOW.user_initials : ''
    };

    if ($window.NOW && $window.NOW.user_avatar) {
        $scope.avatarProfile.userImage = $window.NOW.user_avatar;
    }

    /* ---------------------------------------------------------------- 2 ----
     * Collapse + responsive behaviour.
     * -------------------------------------------------------------------- */
    $scope.collapse = function () {
        $rootScope.$emit('sp-navbar-collapse');
    };

    $scope.openPopUp = function () {
        var url = '$chat_support.do?queueID=' + $scope.data.connect_support_queue_id;
        $window.open(url, 'popup', 'width=900, height=600');
    };

    var nav = $window.document.getElementById('responsiveNav');

    function isMDScreenSize() {
        return nav ? nav.classList.contains('responsive-tablet') : false;
    }

    function updateResponsiveClasses(width) {
        if (!nav) {
            return;
        }
        if (width <= 992) {
            nav.classList.add('responsive-tablet');
            nav.classList.remove('responsive-desktop');
        } else {
            nav.classList.add('responsive-desktop');
            nav.classList.remove('responsive-tablet');
        }
        $scope.showSMAvatar = width <= 992;
        $scope.showAvatar = width > 992;
    }

    // Initial pass (also covers browsers without ResizeObserver).
    updateResponsiveClasses($window.innerWidth);
    $scope.showAvatar = $scope.user.logged_in && $window.innerWidth > 992;
    $scope.showSMAvatar = $scope.user.logged_in && $window.innerWidth <= 992;

    if (nav && $window.ResizeObserver) {
        var observer = new $window.ResizeObserver(function (entries) {
            if (entries && entries[0]) {
                updateResponsiveClasses(entries[0].contentRect.width);
                $scope.showAvatar = $scope.user.logged_in && !isMDScreenSize();
                $scope.showSMAvatar = $scope.user.logged_in && isMDScreenSize();
            }
        });
        observer.observe(nav);
        $scope.$on('$destroy', function () {
            observer.disconnect();
        });
    }

    $rootScope.$on('sp.avatar_changed', function () {
        $scope.avatarProfile = angular.extend({}, $scope.avatarProfile);
    });

    $scope.isAgentChatConfigured = typeof g_has_agent_chat_config !== 'undefined'
        ? g_has_agent_chat_config
        : false;

    // Keyboard navigation for the header dropdowns.
    $timeout(function () {
        var navbarElement = $element.find('.navbar');
        if (navbarElement.length > 0 && spAriaUtil && spAriaUtil.initDropdownKeyboardNav) {
            spAriaUtil.initDropdownKeyboardNav(navbarElement, {
                checkMdScreenSize: true,
                isMDScreenSize: function () {
                    return $window.matchMedia('(max-width: 992px)').matches;
                }
            });
        }
    });
};

sp_header_footer.css:
/* ==========================================================================
 * Enterprise Digital Portal — HEADER styles
 * ==========================================================================
 * Glassmorphic navbar over the warm neutral page background.
 *
 * Structure (mirrors template.html):
 *   1. navbar shell + glass
 *   2. brand / logo
 *   3. nav links
 *   4. search slot
 *   5. theme toggle slot
 *   6. avatar / dropdown
 *   7. responsive media queries   <- MANDATORY fallbacks, do not delete
 *   8. reduced motion + forced colors
 *
 * Colour values come from the theme's `--edp-*` runtime tokens so the header
 * re-themes instantly when `data-edp-theme` flips on <html>.
 * Sizes/spacing come from the theme's $sp-* SCSS scales.
 * ========================================================================== */

/* ---------------- 1. NAVBAR SHELL -------------------------------------- */
.navbar {
    transition: 250ms opacity ease-in-out;
    border: 0;
    border-bottom: $sp-navbar-bottom-width solid var(--edp-hairline);
    margin-bottom: 0;
    border-radius: 0;
    background-color: var(--edp-surface-strong);
    -webkit-backdrop-filter: blur(var(--edp-blur-strong)) saturate(160%);
    backdrop-filter: blur(var(--edp-blur-strong)) saturate(160%);
    box-shadow: var(--edp-shadow-1);
}

.navbar-fade {
    opacity: 0.4;
}

.navbar-inverse.is-native {
    background-color: var(--edp-bg-elevated);
}

header[role='banner'],
.nav > li > a {
    max-height: 60px;
}

.navbar .toggle-dropdown {
    height: 60px;
}

.navbar-right {
    padding-right: 0;
    padding-left: $sp-space-1;
}

.navbar-nav {
    margin: 0;
}

/* ---------------- 2. BRAND / LOGO -------------------------------------- */
.navbar-brand {
    max-height: 60px;
    padding: 0;
    padding-bottom: $sp-space-1;
}

.navbar-brand img,
.navbar-brand span {
    margin-left: $sp-logo-margin-x;
    margin-right: $sp-logo-margin-x;
    margin-top: $sp-logo-margin-y;
    margin-bottom: $sp-logo-margin-y;
    display: block;
    max-height: $sp-logo-max-height;
    max-width: $sp-logo-max-width;
    position: relative;
    top: 50%;
    -webkit-transform: translateY(-50%);
    -ms-transform: translateY(-50%);
    transform: translateY(-50%);
    overflow: hidden;
    width: calc(100% - 3rem);
}

.navbar-brand span {
    color: var(--edp-text);
    font-size: $sp-text-md;
    font-weight: 700;
}

/* ---------------- 3. NAV LINKS ----------------------------------------- */
.navbar-inverse .navbar-nav > li > a {
    color: var(--edp-text);
    font-size: $sp-text-sm;
    font-weight: 600;
    border-radius: var(--edp-radius-pill);
    margin: $sp-space-2 $sp-space-1;
    padding: $sp-space-2 $sp-space-3;
    transition: background-color 160ms ease, color 160ms ease;
}

.navbar-inverse .navbar-nav > li > a:hover,
.navbar-inverse .navbar-nav > li > a:focus {
    background-color: var(--edp-accent-soft);
    color: var(--edp-accent-ink);
}

.navbar-inverse .navbar-nav > .open > a,
.navbar-inverse .navbar-nav > .active > a {
    background-color: var(--edp-accent-soft-hover);
    color: var(--edp-accent-ink);
}

.nav > li > a span.fa {
    margin-left: $sp-space-1;
    font-size: $sp-icon-sm;
}

.navbar-inverse .navbar-toggle {
    border-color: $sp-navbar-toggle-border-color;
    border-radius: var(--edp-radius-sm);
}

.navbar-inverse .navbar-toggle .icon-bar {
    background-color: var(--edp-text);
}

.navbar-inverse .navbar-toggle:hover,
.navbar-inverse .navbar-toggle:focus {
    background-color: var(--edp-accent-soft);
}

.scrollable-dropdown {
    max-height: 80vh;
    overflow: auto;
    height: auto;
}

.is-native .scrollable-dropdown {
    max-height: 100vh;
    overflow: scroll;
    height: auto;
}

/* ---------------- 4. SEARCH SLOT --------------------------------------- */
.edp-navbar-search {
    display: flex;
    align-items: center;
    padding: $sp-space-2 $sp-space-2;
    min-width: 200px;
}

.edp-navbar-search .form-control,
.edp-navbar-search input[type='text'] {
    background-color: var(--edp-surface-sunken);
    border: 1px solid var(--edp-hairline-strong);
    border-radius: var(--edp-radius-pill);
    color: var(--edp-text);
    font-size: $sp-text-sm;
    height: 34px;
}

.edp-navbar-search .input-group-btn > .btn {
    border-radius: var(--edp-radius-pill);
    background-color: transparent;
    border-color: var(--edp-hairline-strong);
    color: var(--edp-accent-ink);
}

/* ---------------- 5. THEME TOGGLE SLOT -------------------------------- */
.edp-navbar-theme {
    display: flex;
    align-items: center;
    padding: $sp-space-2 $sp-space-2;
}

/* ---------------- 6. AVATAR / DROPDOWN -------------------------------- */
/* No `!important` on background-color here — it would block ng-style from
   painting the avatar image. */
.navbar-avatar {
    display: inline-block;
    margin-right: $sp-space-2;
    vertical-align: middle;
}

.navbar-inverse .dropdown-menu {
    background-color: var(--edp-surface-strong);
    border: 1px solid var(--edp-hairline);
    border-radius: var(--edp-radius);
    box-shadow: var(--edp-shadow-2);
    -webkit-backdrop-filter: blur(var(--edp-blur-strong));
    backdrop-filter: blur(var(--edp-blur-strong));
}

.navbar-inverse .dropdown-menu > li > a {
    color: var(--edp-text);
    font-size: $sp-text-sm;
    padding: $sp-space-2 $sp-space-4;
}

.navbar-inverse .dropdown-menu > li > a:hover,
.navbar-inverse .dropdown-menu > li > a:focus {
    background-color: var(--edp-accent-soft);
    color: var(--edp-accent-ink);
}

.breadcrumb-container {
    background-color: transparent;
}

/* ---------------- 7. RESPONSIVE (MANDATORY FALLBACKS) ----------------- */
/* The `.responsive-desktop` / `.responsive-tablet` classes are applied by the
   framework/client script, but the media queries below are REQUIRED as
   fallbacks — without them the menu is hidden on desktop. */
@media (min-width: 993px) {
    .navbar-right {
        display: flex !important;
        height: auto !important;
        align-items: center;
    }
}

@media (max-width: 992px) {
    .navbar-toggle {
        display: block;
    }
    .navbar-header {
        float: none;
    }
    .navbar-left,
    .navbar-right {
        float: none !important;
    }
    .navbar-nav {
        float: none !important;
    }
    .navbar-nav > li {
        float: none;
    }
    .navbar-nav > li > a {
        padding-top: $sp-space-3;
        padding-bottom: $sp-space-3;
    }
    .edp-navbar-search {
        min-width: 0;
        width: 100%;
    }
}

.responsive-desktop .navbar-right {
    display: flex !important;
    height: auto !important;
    align-items: center;
}

.responsive-tablet {
    .navbar-toggle {
        display: block;
    }
    .navbar-header {
        float: none;
    }
    .navbar-left,
    .navbar-right {
        float: none !important;
    }
    .navbar-nav {
        float: none !important;
    }
    .navbar-nav > li {
        float: none;
    }
    .navbar-nav > li > a {
        padding-top: $sp-space-3;
        padding-bottom: $sp-space-3;
    }
    .nav > li > a {
        padding-right: $sp-space-2;
        padding-left: $sp-space-2;
    }
    .navbar-brand img,
    .navbar-brand span {
        max-width: $sp-logo-mobile-max-width;
    }
}

/* ---------------- 8. REDUCED MOTION + FORCED COLORS ------------------- */
@media (prefers-reduced-motion: reduce) {
    .navbar,
    .navbar-inverse .navbar-nav > li > a {
        transition: none;
    }
}

@media screen and (-ms-high-contrast: active), (forced-colors: active) {
    .navbar-brand,
    .navbar-nav > li > a,
    .skip-link,
    .btn.btn-primary,
    .btn.btn-danger,
    .navbar-inverse .navbar-toggle {
        &:focus {
            outline-offset: -4px !important;
        }
    }
}

sp_header_footer.script:
/* ==========================================================================
 * Enterprise Digital Portal — HEADER server script
 * ==========================================================================
 * CRITICAL: NO IIFE wrapper. Header/footer server scripts run in a context
 * where wrapping in `(function(){ ... })();` breaks `data` binding.
 *
 * SCOPED APP (x_exls_enterpris_0): the OOTB Stock Header "Language selector"
 * line — `data.langSelector = pm.isActive('com.glide.i18n') ? ... : "";` —
 * is deliberately OMITTED. `pm` is a global-scope-only object and throws
 * `"pm" is not defined` in a scoped application on every page load.
 *
 * Scoped-safe APIs only: gs.info / gs.error (never gs.print),
 * new GlideDateTime() (never nowDateTime()), explicit GlideRecord.
 * ========================================================================== */

/* ---- Portal configuration ------------------------------------------------ */
data.connect_support_queue_id = $sp.getValue('sp_chat_queue');
data.login_page = $sp.getValue('login_page');
data.profileBtnMsg = gs.getMessage('User options');
data.toggleMsg = gs.getMessage('Toggle navigation');
data.searchMsg = gs.getMessage('Search Enterprise Digital');

/* ---- SPMenu wiring ------------------------------------------------------- *
 * The menu is NOT injected into this template directly. The platform stores
 * the sp_instance_menu sys_id on sp_portal.sp_rectangle_menu; we read it and
 * hand the widget to <sp-widget widget="::data.menu">.
 * All three menu display requirements must hold:
 *   portal.theme  +  theme.header  +  portal.mainMenu
 * -------------------------------------------------------------------------- */
var menuInstanceId = $sp.getValue('sp_rectangle_menu');
data.menu = $sp.getWidgetFromInstance(menuInstanceId);

data.hasMenuItems = false;
data.hasLogin = false;

if (data.menu && data.menu.data) {
    // REQUIRED — without this the menu renders twice.
    data.menu.data.replace = true;

    if (data.menu.data.menu && data.menu.data.menu.items) {
        // REQUIRED — controls the mobile hamburger button visibility.
        data.hasMenuItems = data.menu.data.menu.items.length > 0;

        for (var i in data.menu.data.menu.items) {
            var item = data.menu.data.menu.items[i];
            if (item.type == 'page' && item.sp_page == data.login_page) {
                data.hasLogin = true;
            }
        }
    }
} else {
    gs.info('[EDP header] No menu instance resolved from sp_rectangle_menu. ' +
        'Check that ServicePortal.mainMenu is set.');
}

/* ---- Embedded widgets ---------------------------------------------------- *
 * Search  : OOTB `typeahead-search` widget, reused verbatim (no custom search
 *           widget was built — OOTB already does the job).
 * Theme   : the EDP Theme Toggle widget. Rendered here so the light/dark
 *           switch is reachable from every page of the portal.
 * Each lookup is guarded so a missing widget degrades gracefully instead of
 * blanking the whole header.
 * -------------------------------------------------------------------------- */
data.search = '';
data.themeToggle = '';

try {
    data.search = $sp.getWidget('typeahead-search', {
        size: 'sm',
        title: data.searchMsg
    }) || '';
} catch (searchErr) {
    gs.error('[EDP header] Could not load OOTB typeahead-search widget: ' + searchErr);
}

try {
    data.themeToggle = $sp.getWidget('x_exls_enterpris_0_edp_theme_toggle', {}) || '';
} catch (toggleErr) {
    gs.error('[EDP header] Could not load EDP theme toggle widget: ' + toggleErr);
}
